package com.bank.scoped;

// Immutable, implicitly-passed request context. No set() → cannot be mutated.
public final class RequestContext {
    // Bound only for the dynamic scope of a run()/call(); auto-removed afterwards.
    public static final ScopedValue<String> CURRENT_USER = ScopedValue.newInstance();
    public static final ScopedValue<String> REQUEST_ID   = ScopedValue.newInstance();

    private RequestContext() { }
}
