package com.bank.scoped;

import java.math.BigDecimal;
import java.util.logging.Logger;

// Reads the scoped context WITHOUT it being passed as a parameter anywhere.
public class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());

    public void transfer(String from, String to, BigDecimal amount) {
        // KEY.get() reads the value bound by the enclosing where(...).run(...)
        String user = RequestContext.CURRENT_USER.get();
        String reqId = RequestContext.REQUEST_ID.get();
        log.info(() -> "[req=" + reqId + " user=" + user + "] transfer Rs." + amount
            + " " + from + "->" + to);
        audit(amount);     // nested call also sees the same scoped values
    }

    private void audit(BigDecimal amount) {
        // No parameters needed — the context flows implicitly down the call tree.
        log.info(() -> "[req=" + RequestContext.REQUEST_ID.get()
            + " user=" + RequestContext.CURRENT_USER.get() + "] audited Rs." + amount);
    }
}
