package com.bank.scoped;

import java.math.BigDecimal;
import java.util.UUID;
import java.util.concurrent.Executors;
import java.util.concurrent.ExecutorService;
import java.util.logging.Logger;

public class ScopedValueDemo {
    private static final Logger log = Logger.getLogger(ScopedValueDemo.class.getName());

    public static void main(String[] args) throws Exception {
        TransferService service = new TransferService();

        // One virtual thread per request; bind context ONLY for the request scope.
        try (ExecutorService vexec = Executors.newVirtualThreadPerTaskExecutor()) {
            vexec.submit(() -> handleRequest(service, "rajesh")).get();
            vexec.submit(() -> handleRequest(service, "priya")).get();
        }

        // After every scope ended, the binding is gone → reading throws (no leak).
        try {
            RequestContext.CURRENT_USER.get();
        } catch (Exception e) {
            log.warning("outside any scope: CURRENT_USER unbound (no leak) → " + e.getClass().getSimpleName());
        }
    }

    static void handleRequest(TransferService service, String user) {
        String reqId = UUID.randomUUID().toString().substring(0, 8);
        // BIND both values for the dynamic extent of this run(); auto-torn-down after.
        ScopedValue.where(RequestContext.CURRENT_USER, user)
            .where(RequestContext.REQUEST_ID, reqId)
            .run(() -> {
                service.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));

                // Nested REBIND: an operator acts on behalf of the user for a sub-task.
                ScopedValue.where(RequestContext.CURRENT_USER, "operator-" + user)
                    .run(() -> service.transfer("SAV2001", "CUR3001", new BigDecimal("1000")));

                // Back outside the nested scope, CURRENT_USER reverts to `user`.
                service.transfer("SAV2001", "CUR3001", new BigDecimal("500"));
            });
    }
}
